mat2 obtenirMatriceRotation(in float angle) {
    float cosinus = cos(angle), sinus = sin(angle);
    return mat2(cosinus, sinus, -sinus, cosinus);
}

float ondeTriangulaire(in float valeur) {
    return abs((valeur - floor(valeur)) - 0.5);
}

vec3 ondulationCroisee3D(in vec3 position) {
    return vec3(
        abs((position.z + abs((position.y - floor(position.y)) - 0.5) - floor(position.z + abs((position.y - floor(position.y)) - 0.5))) - 0.5),
        abs((position.z + abs((position.x - floor(position.x)) - 0.5) - floor(position.z + abs((position.x - floor(position.x)) - 0.5))) - 0.5),
        abs((position.y + abs((position.x - floor(position.x)) - 0.5) - floor(position.y + abs((position.x - floor(position.x)) - 0.5))) - 0.5)
    );
}

float calculerBruitFractal(in vec3 position, in float vitesseAnimation) {
    float echelle = 0.6;
    float valeurAccumulee = 0.1;
    vec3 positionEchelle = position;

    for (float octave = 0.0; octave <= 4.0; octave++) {
        vec3 ondulation = ondulationCroisee3D(positionEchelle);
        position += (ondulation + iTime * vitesseAnimation);
        positionEchelle *= 2.0;
        echelle *= 1.5;
        position *= 1.3;
        valeurAccumulee += (ondeTriangulaire(position.z + ondeTriangulaire(position.x + ondeTriangulaire(position.y)))) / echelle;
        positionEchelle += 0.14;
    }
    return valeurAccumulee;
}

vec2 calculerTrajectoireTunnel(float avanceeZ) {
    return vec2(
        sin(avanceeZ * 0.1) * 4.0 + cos(avanceeZ * 0.03) * 2.0,
        cos(avanceeZ * 0.07) * 3.0 + sin(avanceeZ * 0.05) * 1.8
    );
}

float estimerDistanceScene(vec3 position) {
    vec2 centreTunnel = calculerTrajectoireTunnel(position.z);
    vec3 positionRelative = position;
    positionRelative.xy -= centreTunnel;

    float distanceParoiTunnel = 6.0 - length(positionRelative.xy);
    float bruitRelief = calculerBruitFractal(position * 0.2, 0.03);

    positionRelative.xy *= obtenirMatriceRotation(position.z * 0.15 + iTime * 0.1);

    vec2 posAnneau = positionRelative.xy;
    float angleAnneau = atan(posAnneau.y, posAnneau.x);
    float distAnneau = length(posAnneau);
    distAnneau += sin(angleAnneau * 6.0 + position.z * 2.0) * 0.25;

    float distanceSerpentinInterne = abs(distAnneau - 1.8) - 0.2;
    float distanceCoeurLuminescent = length(positionRelative.xy) - 0.3;

    float distanceGeometrieBrute = min(distanceParoiTunnel, min(distanceSerpentinInterne, distanceCoeurLuminescent));
    return distanceGeometrieBrute - bruitRelief * 0.6;
}

vec3 calculerNormaleTetraedre(in vec3 position) {
    vec2 epsilon = vec2(-1.0, 1.0) * 0.008;
    return normalize(
        epsilon.yxx * estimerDistanceScene(position + epsilon.yxx) +
        epsilon.xxy * estimerDistanceScene(position + epsilon.xxy) +
        epsilon.xyx * estimerDistanceScene(position + epsilon.xyx) +
        epsilon.yyy * estimerDistanceScene(position + epsilon.yyy)
    );
}

vec3 calculerPositionCamera(float avanceeZ) {
    return vec3(calculerTrajectoireTunnel(avanceeZ), avanceeZ);
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 uvNormalisees = coordFragment.xy / iResolution.xy;
    vec2 coordonnesCentrees = uvNormalisees - 0.5;
    coordonnesCentrees.x *= iResolution.x / iResolution.y;

    float avanceeTps = iTime * 10.0;
    vec3 origineRayon = calculerPositionCamera(avanceeTps);
    vec3 cibleCamera = calculerPositionCamera(avanceeTps + 2.5);

    float angleRoulis = sin(iTime * 0.15) * 0.8;
    vec3 directionRegard = normalize(cibleCamera - origineRayon);
    vec3 axeVerticalBrut = vec3(sin(angleRoulis), cos(angleRoulis), 0.0);
    vec3 axeHorizontalCam = normalize(cross(directionRegard, axeVerticalBrut));
    vec3 axeVerticalCam = normalize(cross(axeHorizontalCam, directionRegard));
    vec3 directionRayon = normalize(coordonnesCentrees.x * axeHorizontalCam + coordonnesCentrees.y * axeVerticalCam + 1.1 * directionRegard);

    float distanceParcourue = 0.0;
    float distanceDistortion = 0.0;

    vec3 volLumineuxAccumule = vec3(0.0);
    vec3 couleurLaser = vec3(0.0);

    for (int stepIndex = 0; stepIndex < 120; stepIndex++) {
        vec3 positionCourante = origineRayon + directionRayon * distanceParcourue;
        distanceDistortion = estimerDistanceScene(positionCourante);

        if (abs(distanceDistortion) < 0.004 || distanceParcourue > 60.0) break;

        distanceParcourue += distanceDistortion * 0.5;

        float densiteAura = max(0.0, (0.4 - distanceDistortion));
        vec3 teinteAura = 0.5 + 0.5 * cos(positionCourante.z * 0.2 + vec3(0.0, 2.0, 4.0));
        volLumineuxAccumule += teinteAura * densiteAura * 0.08;

        vec2 centreTunnel = calculerTrajectoireTunnel(positionCourante.z);
        float distCentreStep = length(positionCourante.xy - centreTunnel);
        couleurLaser += vec3(0.2, 0.5, 1.0) * (0.015 / (distCentreStep + 0.05)) * exp(-distanceParcourue * 0.04);
    }

    vec3 couleurFinale = vec3(0.005, 0.01, 0.02);

    if (distanceParcourue < 60.0) {
        vec3 positionImpact = origineRayon + directionRayon * distanceParcourue;
        vec3 normaleSurface = calculerNormaleTetraedre(positionImpact);

        vec3 positionLumiereFluctuante = calculerPositionCamera(avanceeTps + 6.0);
        vec3 directionLumiere = normalize(positionLumiereFluctuante - positionImpact);

        float bruitTexture = calculerBruitFractal(positionImpact * 0.15, 0.02);
        float differeLumiere = clamp(dot(normaleSurface, directionLumiere), 0.0, 1.0);
        float effetFresnel = pow(clamp(1.0 + dot(normaleSurface, directionRayon), 0.0, 1.0), 4.0);
        float occlusionalAmbiante = clamp(estimerDistanceScene(positionImpact + normaleSurface * 1.5), 0.0, 1.0);

        vec3 couleurBaseA = vec3(0.02, 0.05, 0.15);
        vec3 couleurBaseB = 0.5 + 0.5 * sin(positionImpact.z * 0.1 + vec3(0.0, 1.5, 3.0));

        couleurFinale = mix(couleurBaseA, couleurBaseB, bruitTexture);

        vec3 refletSpeculaire = vec3(1.0, 0.9, 0.8) * pow(max(0.0, dot(reflect(-directionLumiere, normaleSurface), -directionRayon)), 16.0);

        couleurFinale = couleurFinale * (differeLumiere + 0.2) + (effetFresnel * couleurBaseB * 2.0 + refletSpeculaire) * occlusionalAmbiante;
        couleurFinale *= occlusionalAmbiante;

        couleurFinale = mix(couleurFinale, vec3(0.01, 0.02, 0.05), smoothstep(15.0, 60.0, distanceParcourue));
    }

    couleurFinale += volLumineuxAccumule + couleurLaser;

    couleurFinale = couleurFinale / (1.0 + couleurFinale);
    couleurFinale = pow(couleurFinale, vec3(0.4545));

    float vignettage = pow(16.0 * uvNormalisees.x * uvNormalisees.y * (1.0 - uvNormalisees.x) * (1.0 - uvNormalisees.y), 0.25);
    couleurFinale *= 0.2 + 0.8 * vignettage;

    couleurFragment = vec4(couleurFinale * smoothstep(0.0, 2.0, iTime), 1.0);
}
